B=Block('theory')
PAGES={76:[189,190,191],77:[191,192,193,194,195],78:[195,196],79:[199,200],80:[201,202],81:[202,203,204],82:[206,207],83:[207,208]}
CACHE={};NUMERIC=[]
def verify(label,a,b):
 assert math.isclose(a,b,rel_tol=1e-8,abs_tol=1e-8),(label,a,b)
 NUMERIC.append(dict(label=label,actual=a,expected=b))
def degrees(p,a,o,b):
 u=subv(p[a],p[o]);v=subv(p[b],p[o]);return math.degrees(math.acos(max(-1,min(1,sum(x*y for x,y in zip(u,v))/math.hypot(*u)/math.hypot(*v)))))
def labels(p):return {k:k.replace('1','₁').replace('2','₂') for k in p if not k.startswith('_')}
def add(n,title,statement,answer,rows,p,v,views=None,checks=(),cases=(),**kw):
 B.add(n,'single',statement,answer,rows,p,v,views,checks,cases,collection='theory',title=title,printed=PAGES[n],labels=labels(p),**kw)
 CACHE[n]=deepcopy((rows,p,v,views,checks,cases))
def question(n,statement,answer,rows,p,v,views=None,checks=(),cases=(),**kw):
 B.add(n,'single',statement,answer,rows,p,v,views,checks,cases,collection='selfcheck',title='Вопрос '+str(n),printed=[209 if n<=10 else 210],labels=labels(p),**kw)
def qcopy(n,theory,statement):
 source=next(x for x in B.theory if x['number']==theory)
 rows,p,v,views,checks,cases=deepcopy(CACHE[theory]);question(n,statement,source['answer'],rows,p,v,views,checks,cases,notes=source['notes'])
 B.models[-1]['model']=deepcopy(next(x for x in B.models if x['collection']=='theory' and x['number']==theory)['model'])
def case_view(v,p,i,step):
 names={k:k+'__case'+str(i) for k in p}
 def ren(x):
  if isinstance(x,str):return names.get(x,x)
  if isinstance(x,list):return [ren(z) for z in x]
  if isinstance(x,dict):return {k:ren(z) for k,z in x.items()}
  return x
 B.models[-1]['model']['views']['step-'+str(step)]={**ren(deepcopy(v)),'label':'Шаг '+str(step)}

