for s,p,v,i in [(1,zp,zv,1),(3,lem,lemf,2),(5,ep,ef,3),(6,ip,iff,4),(7,op,of,5),(8,sp,sf,6),(2,q3p,q3f,7)]:case_view(v,p,i,s)

question(3,'Объясните, почему две окружности не могут иметь три общие точки.','У двух различных окружностей не более двух общих точек; совпадающие окружности имеют бесконечно много общих точек.',[row('Нужна ли оговорка в формулировке?','Да: речь о двух различных окружностях. Если окружности совпадают, каждая их точка общая. Предположим, что разные окружности проходят через три различные точки A, B, C.','Различие двух окружностей.',77),row('Почему точки A, B, C не лежат на одной прямой?','Прямая пересекает окружность не более чем в двух точках. Значит три общие точки образуют невырожденный треугольник.','Взаимное расположение прямой и окружности.',76),row('Где должны находиться центры?','Каждый центр равноудалён от A и B, а также от B и C. Поэтому каждый принадлежит серединным перпендикулярам к AB и BC. Эти две прямые пересекаются в единственной точке O.','Свойство серединного перпендикуляра.',[40, 70]),row('Как получаем противоречие?','Оба центра совпадают с O, а оба радиуса равны OA. Окружность с заданным центром и радиусом единственна, значит окружности совпадают. Это противоречит предположению, что они различны.','Определение окружности.',[21, 77])],q3p,q3v,[q3v,q3v,q3f,q3f],checks=q3ch,notes=['Уточнено необходимое слово «различные», отсутствующее в краткой формулировке вопроса источника.'])
