# 78: each position has its own scene; a tangent is a line, not a segment.
def tangent_scene(d,R=4,r=2):
 p={'O1':[0,0],'O2':[d,0],'_R':[0,R],'_r':[d,r]};v=sc(['O1','O2'],[],circles=[circle('O1','_R'),circle('O2','_r')]);f=deepcopy(v);checks=[];count=0
 for sign,k in [(1,R-r),(-1,R+r)]:
  if d<k-1e-9:continue
  nx=k/d;ys=[0] if abs(nx-1)<1e-9 else [math.sqrt(1-nx*nx),-math.sqrt(1-nx*nx)]
  for ny in ys:
   count+=1;name=str(count);A='T'+name;D='_L'+name;E='_U'+name;n=[nx,ny];t=[-ny,nx]
   # A line is infinite in the viewer: its two defining points need not
   # shrink the touching circles. For internal contact keep those points
   # inside the circle's vertical extent, leaving room for O1/O2/K labels.
   span=R if abs(d-(R-r))<1e-9 else 7
   p[A]=[R*x for x in n];p[D]=addv(p[A],[-span*x for x in t]);p[E]=addv(p[A],[span*x for x in t]);Q='_S'+name;p[Q]=[d+sign*r*nx,sign*r*ny]
   f['lines']=f.get('lines',[])+[[D,E]]
   checks += [perp('O1',A,D,E),perp('O2',Q,D,E),equal(('O1',A),('O1','_R')),equal(('O2',Q),('O2','_r')),col(D,A,E)]
   verify('common tangent second contact '+str(d)+' '+name,dist(p['O2'],p[Q]),r)
 # At internal/external contact d=R-r or R+r, the shared contact is
 # K=(R,0). Both centre-to-contact radii are horizontal; its common
 # tangent is vertical. Reveal these proof objects only in the case view.
 if d and (abs(d-(R-r))<1e-9 or abs(d-(R+r))<1e-9):
  p['K']=[R,0]
  tangent_index=next(i for i in range(1,count+1) if abs(p['T'+str(i)][0]-R)<1e-9 and abs(p['T'+str(i)][1])<1e-9)
  lo='_L'+str(tangent_index);hi='_U'+str(tangent_index)
  f=more(f,['K'],[['O1','K'],['O2','K']],rightAngles=[rt('O1','K',hi)])
  checks += [col('O1','O2','K'),equal(('O1','K'),('O1','_R')),equal(('O2','K'),('O2','_r')),perp('O1','K',lo,hi)]
  verify('touch K on first circle '+str(d),dist(p['O1'],p['K']),R)
  verify('touch K on second circle '+str(d),dist(p['O2'],p['K']),r)
 return p,v,f,checks,count
T=[tangent_scene(d) for d in [1,2,4,6,8]]
assert [z[4] for z in T]==[0,1,2,3,4]
tp,tv,tf,tch,_=T[4]
tdefinition=more(tv,(),lines=[tf['lines'][0],tf['lines'][2]],dashSegments=[['O1','O2']])
trows=[row('Что значит общая касательная?','Это прямая, касающаяся обеих окружностей. В точках касания она перпендикулярна обоим радиусам. Внешняя общая касательная оставляет оба центра по одну сторону от себя; внутренняя — по разные стороны. Слова «внешняя» и «внутренняя» относятся к расположению центров относительно прямой.','Определение; свойство радиуса в точке касания.',[42, 78]),row('Сколько касательных, если окружности одна внутри другой?','Если d < R − r, касательная к меньшей окружности проходит через внутреннюю точку большей и потому пересекает большую в двух точках. Общей касательной нет. При общем центре и разных радиусах вывод тот же.','Касательная не пересекает внутреннюю область круга.',[76,77,78]),row('Что происходит при внутреннем касании?','При d = R − r > 0 обе окружности касаются в K на линии центров. Перпендикуляр к O₁O₂ в K касается обеих окружностей. Другой общей касательной быть не может: для внешней касательной разность перпендикулярных расстояний центров до неё равна R − r = d, а равенство проекции и длины возможно лишь при перпендикулярности линии центров этой касательной.','Радиус и касательная; длина проекции не превосходит длину отрезка.',[42, 78]),row('Почему при пересечении общих касательных две?','Пусть R − r < d < R + r. Внешняя касательная должна иметь разность расстояний центров R − r. Проекция O₁O₂ на перпендикуляр к ней поэтому равна R − r. Так как 0 ≤ R − r < d, есть два зеркальных положения такой прямой — по разные стороны линии центров. Внутренняя потребовала бы проекции длиной R + r > d, что невозможно.','Прямоугольный треугольник по гипотенузе и катету; свойство касательной.',[36, 78]),row('Почему при внешнем касании касательных три?','Если d = R + r, остаются две внешние касательные. Внутренняя проходит через общую точку K перпендикулярно линии центров. Два зеркальных внутренних положения сливаются в одну прямую. Получается 2 + 1 = 3.','Касание; случай равенства проекции длине.',[77,78]),row('Почему у раздельных окружностей касательных четыре?','При d > R + r возможны два внешних положения с проекцией R − r и два внутренних с проекцией R + r. Обе проекции меньше d, поэтому каждое построение даёт две зеркальные касательные. Всего четыре. Если же совпадают и центры, и радиусы, окружность одна и общих касательных бесконечно много; это отдельный исключительный случай.','Два решения прямоугольного построения; определения окружности и касательной.',[42, 78])]
cases=[(z[0],z[2],label,s,z[3],labels(z[0])) for z,label,s in zip(T[:4],['Окружности вложены: 0','Внутреннее касание: 1','Пересечение: 2','Внешнее касание: 3'],[2,3,4,5])]
add(78,'Общие касательные двух окружностей','Определите внешние и внутренние общие касательные. Исследуйте их число при всех взаимных положениях двух различных окружностей.','Число общих касательных: 0, 1, 2, 3 или 4; при совпадающих окружностях — бесконечно много.',trows,tp,tv,[tdefinition,tv,tv,tv,tv,tf],checks=tch,cases=cases,notes=['Классификация 0–4 относится к различным окружностям положительных радиусов. Совпадение окружностей выделено отдельно.'])
for i,(z,s) in enumerate(zip(T[:4],[2,3,4,5]),1):case_view(z[2],z[0],i,s)
