# 79: three-point arc notation removes the small/large ambiguity.
def circle_points(angles,r=4):return dict(O=[0,0],**{k:polar([0,0],a,r) for k,a in angles.items()})
def equal_radii(names):return equal(*[('O',n) for n in names])
ap=circle_points(dict(A=115,B=0,C=145,D=180));av=sc('ABCDO',[],circles=[circle('O','A')]);af=more(av,(),[['O','A'],['O','B'],['O','C'],['O','D']],angleArcs=[arc('O','B','A')]);ach=[equal_radii('ABCD'),ang('A','O','B',115),ang('A','O','C',30),col('B','O','D')]
verify('source figure257 CAB',degrees(ap,'C','O','B'),145)
hp=circle_points(dict(A=180,B=0,L=270));hv=sc('ABLO',[['A','B']],circles=[circle('O','A')]);hch=[equal_radii('ABL'),col('A','O','B')]
arows=[row('Как различить две дуги с одинаковыми концами?','Две различные точки A и B разделяют окружность на две дуги. Чтобы выбрать одну, укажем промежуточную точку: дуга ACB проходит через C, а другая дуга — через точку, не лежащую на первой. Запись «дуга AB» используем только когда выбор однозначен.','Определение и обозначение дуги.',79),row('Что такое центральный угол и полуокружность?','У центрального угла вершина находится в центре O. Если концы дуги соединены диаметром, эта дуга — полуокружность. Развёрнутому центральному углу AOB соответствуют две полуокружности по 180°.','Определение центрального угла и полуокружности.',79),row('Как измерить меньшую и большую дуги?','Пусть обычный центральный угол AOB равен α, 0 < α < 180°. Дуга AB внутри этого угла меньше полуокружности, её мера α. Другая дуга больше полуокружности, её мера 360° − α. Их сумма всегда 360°. Для концов диаметра обе меры равны 180°.','Определение градусной меры дуги.',79),row('Как применить это к рисунку 257?','Дано ∠AOB = 115° и ∠AOC = 30°, причём A лежит на дуге CB, не содержащей D. Поэтому дуга CAB = 30° + 115° = 145°. Дуга ADB = 360° − 115° = 245°; дуга CDB = 360° − 145° = 215°. BD — диаметр, значит дуга DB = 180°.','Сложение смежных дуг и дополнение до 360°.',79)]
add(79,'Градусная мера дуги окружности','Объясните обозначения и градусные меры дуг, определите центральный угол и полуокружность; разберите данные рисунка 257.','Мера меньшей дуги равна центральному углу α, большей — 360° − α; полуокружность имеет меру 180°.',arows,ap,av,[av,av,af,af],checks=ach,cases=[(hp,hv,'Две полуокружности',2,hch,labels(hp))]);case_view(hv,hp,1,2)
question(6,'Какой угол называется центральным углом окружности?','Угол с вершиной в центре окружности.',[row('Где расположена вершина?','Вершина O совпадает с центром окружности. Стороны угла — лучи OA и OB; точки A и B находятся на окружности.','Определение центрального угла.',79),row('С какой дугой он связан?','Обычный центральный угол AOB измеряет дугу AB внутри него, меньшую полуокружности; при развёрнутом угле обе дуги — полуокружности. Например, ∠AOB = 115° соответствует меньшей дуге 115°.','Градусная мера дуги.',79)],ap,sc('ABO',[],circles=[circle('O','A')]),[sc('ABO',[['O','A'],['O','B']],circles=[circle('O','A')]),af],checks=ach)
question(7,'Какая дуга называется полуокружностью, какая меньше полуокружности, а какая больше?','Диаметр делит окружность на две полуокружности по 180°. Дуга с мерой меньше 180° — меньшая, с мерой больше 180° — большая.',[row('Как получить полуокружность?','Соедини концы дуги. Если получился диаметр, это полуокружность; её мера 180°.','Определение полуокружности.',79),row('Как различить остальные дуги?','Если концы не являются концами диаметра, одна дуга расположена внутри обычного центрального угла и имеет меру α < 180°. Другая имеет меру 360° − α > 180°. Уточняй дугу промежуточной точкой.','Определение меньшей и большей дуг.',79)],hp,hv,[hv,hv],checks=hch,cases=[(ap,af,'Меньшая и большая дуги AB',2,ach,labels(ap))]);case_view(af,ap,1,2)
