# 80: three separate configurations and complete difference-case proof.
def inscribed(A,C,B=90):
 p=circle_points(dict(A=A,B=B,C=C,D=B+180));v=sc('ABC',[['B','A'],['B','C']],circles=[circle('O','A')]);w=more(v,'OD',[['B','D'],['O','A']],angleArcs=[arc('B','A','C')]);ch=[equal_radii('ABCD'),col('B','O','D')]
 return p,v,w,ch
p0,v0,w0,ch0=inscribed(210,270);p1,v1,w1,ch1=inscribed(210,325);p2,v2,w2,ch2=inscribed(200,245)
# In the first case C=D; avoid displaying both names for one point.
p0.pop('D');w0=more(v0,'O',[['O','A']],equalSegments=[eq('O','A'),eq('O','B')]);ch0=[equal_radii('ABC'),col('B','O','C')]
for p,expected in [(p0,30),(p1,57.5),(p2,22.5)]:verify('inscribed three-case',degrees(p,'A','B','C'),expected)
ip=circle_points(dict(A=210,C=330,B=80,E=130));iv=sc('ABCE',[['B','A'],['B','C'],['E','A'],['E','C']],circles=[circle('O','A')]);ich=[equal_radii('ABCE'),ang('A','B','C',60),ang('A','E','C',60)]
h2p=circle_points(dict(A=180,C=0,B=65));h2v=sc('ABC',[['A','B'],['B','C'],['A','C']],circles=[circle('O','A')],rightAngles=[rt('A','B','C')]);h2ch=[equal_radii('ABC'),col('A','O','C'),ang('A','B','C',90)]
irows=[row('Какую дугу выбирают для вписанного угла?','Вершина B лежит на окружности, а стороны пересекают её ещё в A и C. Угол ABC опирается на дугу AC, не содержащую B. Теорема: ∠ABC равен половине меры именно этой дуги.','Определение вписанного угла.',80),row('Как доказать случай, когда BO совпадает со стороной BC?','Тогда BC — диаметр. Проведём OA. В △AOB радиусы OA и OB равны, поэтому ∠ABO = ∠BAO. Угол AOC — внешний угол этого треугольника: ∠AOC = ∠ABO + ∠BAO = 2∠ABC. Он измеряет дугу AC без B, значит ∠ABC = дуга AC/2.','Равнобедренный треугольник, внешний угол и мера дуги.',[18, 31, 79, 80]),row('Что делать, если BO проходит внутри угла ABC?','Продолжим BO до второй точки D окружности. Дуга AC без B разделена точкой D. По первому случаю ∠ABD = дуга AD/2 и ∠DBC = дуга DC/2. Складываем: ∠ABC = (дуга AD + дуга DC)/2 = дуга AC/2.','Первый случай теоремы; сложение углов и дуг.',80),row('Как доказать случай, когда BO находится вне угла ABC?','Проведём тот же диаметр BD. При расположении A, C, D на одной полуокружности в таком порядке ∠ABC = ∠ABD − ∠CBD. По первому случаю это (дуга AD − дуга CD)/2 = дуга AC/2. При обратном порядке A и C меняются ролями: из большего угла и большей дуги вычитаем меньшие. Так разобрано и внешнее положение луча BO.','Первый случай; вычитание углов и вложенных дуг.',80),row('Почему углы, опирающиеся на одну дугу, равны?','Оба вписанных угла равны половине одной и той же дуги. Например, ∠ABC = дуга AC/2 и ∠AEC = дуга AC/2, поэтому они равны. Их вершины должны лежать на другой дуге; одинаковых концов хорд без уточнения дуги недостаточно.','Доказанная теорема о вписанном угле.',80),row('Почему угол на полуокружности прямой?','Если AC — диаметр, дуга AC без вершины B равна 180°. Следовательно, ∠ABC = 180°/2 = 90°.','Теорема о вписанном угле.',80)]
add(80,'Теорема о вписанном угле','Дайте определение вписанного угла, докажите теорему во всех трёх случаях положения центра и выведите два следствия.','Вписанный угол равен половине дуги, не содержащей его вершину; углы одной дуги равны, угол на полуокружности прямой.',irows,p0,v0,[v0,w0,w0,w0,w0,w0],checks=ch0,cases=[(p1,w1,'BO внутри угла: сумма',3,ch1,labels(p1)),(p2,w2,'BO вне угла: разность',4,ch2,labels(p2)),(ip,iv,'Углы одной дуги',5,ich,labels(ip)),(h2p,h2v,'Угол на полуокружности',6,h2ch,labels(h2p))])
for i,(p,v,s) in enumerate([(p1,w1,3),(p2,w2,4),(ip,iv,5),(h2p,h2v,6)],1):case_view(v,p,i,s)
qcopy(9,80,'Какой угол называется вписанным? Сформулируйте и докажите теорему о вписанном угле.')
question(10,'Докажите, что вписанные углы, опирающиеся на одну и ту же дугу, равны.','Оба равны половине одной и той же дуги.',[row('Уточни общую дугу.','Пусть углы ABC и AEC опираются на одну дугу AC. Эта дуга не содержит ни B, ни E; обе вершины расположены на другой дуге.','Определение дуги, на которую опирается угол.',80),row('Примени теорему дважды.','∠ABC = дуга AC/2 и ∠AEC = дуга AC/2. Правые части совпадают, поэтому ∠ABC = ∠AEC.','Теорема о вписанном угле.',80)],ip,iv,checks=ich)
question(11,'Докажите, что вписанный угол, опирающийся на полуокружность, прямой.','Он равен 180°/2 = 90°.',[row('Чему равна дуга?','Если AC — диаметр, любая из двух дуг AC является полуокружностью и имеет меру 180°. Выбираем ту, на которой нет вершины B.','Определение полуокружности.',79),row('Вычисли половину.','∠ABC = дуга AC/2 = 180°/2 = 90°. Значит угол прямой.','Теорема о вписанном угле.',80)],h2p,sc('ABC',tri(),circles=[circle('O','A')]),[sc('ABC',tri(),circles=[circle('O','A')]),h2v],checks=h2ch)

